// dialogs.js
// ==================================================
// WEBSHELF DIALOGS
// ==================================================

(() => {
  let overlay = null;
  let resolver = null;
  let previousFocus = null;
  let restoreBackground = null;

  function ensureDialog() {
    if (overlay) return;

    overlay = document.createElement("div");
    overlay.className = "webshelf-dialog-overlay";
    overlay.hidden = true;
    overlay.innerHTML = `
      <div class="webshelf-dialog" role="dialog" aria-modal="true" aria-labelledby="webshelf-dialog-title" aria-describedby="webshelf-dialog-message">
        <div class="webshelf-dialog-icon" aria-hidden="true">!</div>
        <div class="webshelf-dialog-copy">
          <h2 id="webshelf-dialog-title"></h2>
          <p id="webshelf-dialog-message"></p>
        </div>
        <div class="webshelf-dialog-actions">
          <button class="webshelf-dialog-cancel" type="button">Cancel</button>
          <button class="webshelf-dialog-confirm" type="button">Confirm</button>
        </div>
      </div>`;

    document.body.appendChild(overlay);

    overlay.querySelector(".webshelf-dialog-cancel").addEventListener("click", () => finish(false));
    overlay.querySelector(".webshelf-dialog-confirm").addEventListener("click", () => finish(true));
    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) finish(false);
    });

    document.addEventListener("keydown", (event) => {
      if (overlay.hidden) return;
      if (event.key === "Tab") {
        const buttons = [...overlay.querySelectorAll("button")];
        const target = event.shiftKey ? buttons.at(-1) : buttons[0];
        if ((event.shiftKey && document.activeElement === buttons[0]) || (!event.shiftKey && document.activeElement === buttons.at(-1))) { event.preventDefault(); target.focus(); }
      }
      if (event.key === "Escape") {
        event.preventDefault();
        finish(false);
      }
    });
  }

  function finish(value) {
    if (!overlay || overlay.hidden) return;
    overlay.hidden = true;
    restoreBackground?.(); restoreBackground = null;
    document.body.classList.remove("dialog-open");
    const done = resolver;
    resolver = null;
    const focus = previousFocus;
    previousFocus = null;
    if (focus && typeof focus.focus === "function" && document.contains(focus)) focus.focus();
    done?.(value);
  }

  function confirm(options = {}) {
    ensureDialog();
    if (resolver) finish(false);

    const settings = typeof options === "string" ? { message: options } : options;
    window.WebShelfSearch?.close?.();
    previousFocus = document.activeElement;

    const title = overlay.querySelector("#webshelf-dialog-title");
    const message = overlay.querySelector("#webshelf-dialog-message");
    const confirmButton = overlay.querySelector(".webshelf-dialog-confirm");
    const cancelButton = overlay.querySelector(".webshelf-dialog-cancel");
    const icon = overlay.querySelector(".webshelf-dialog-icon");

    title.textContent = settings.title || "Are you sure?";
    message.textContent = settings.message || "This action cannot be undone.";
    confirmButton.textContent = settings.confirmText || "Confirm";
    cancelButton.textContent = settings.cancelText || "Cancel";
    confirmButton.classList.toggle("danger", Boolean(settings.danger));
    icon.classList.toggle("danger", Boolean(settings.danger));

    overlay.hidden = false;
    restoreBackground = WebShelfRuntime.modalBackground(overlay);
    document.body.classList.add("dialog-open");
    requestAnimationFrame(() => { if (!overlay.hidden) cancelButton.focus(); });

    return new Promise((resolve) => {
      resolver = resolve;
    });
  }

  window.WebShelfDialog = { confirm, close: () => finish(false) };
})();

;

// activity.js
// ==================================================
// WEBSHELF ACTIVITY
// ==================================================

const ACTIVITY_STORAGE_KEY = "webshelf-recently-viewed";
let currentActivityView = "history";
let currentActivityPeriod = "all";

const activityList = document.querySelector("#activity-list");
const activityInfo = document.querySelector("#activity-info");
const activityPeriods = document.querySelector("#activity-periods");
const hiddenSitesTab = document.querySelector("#hidden-sites-tab");

const safeText = (value) => typeof escapeWebShelfText === "function"
  ? escapeWebShelfText(value)
  : String(value ?? "");


function syncHiddenActivityTab() {
  const hiddenCount = typeof getHiddenSites === "function" ? getHiddenSites().length : 0;
  if (hiddenSitesTab) hiddenSitesTab.hidden = hiddenCount === 0;

  if (hiddenCount === 0 && currentActivityView === "hidden") {
    currentActivityView = "history";
    document.querySelectorAll(".activity-tab").forEach((tab) => {
      tab.classList.toggle("active", tab.dataset.view === "history");
    });
  }
}

function applyActivityHash() {
  if (location.hash !== "#hidden") {
    if (currentActivityView === "hidden") {
      currentActivityView = "history";
      document.querySelectorAll(".activity-tab").forEach(tab => tab.classList.toggle("active", tab.dataset.view === "history"));
    }
    return;
  }
  const hiddenCount = typeof getHiddenSites === "function" ? getHiddenSites().length : 0;
  if (!hiddenCount || !hiddenSitesTab) return;
  currentActivityView = "hidden";
  document.querySelectorAll(".activity-tab").forEach((tab) => {
    tab.classList.toggle("active", tab === hiddenSitesTab);
  });
}

function canonicalSite(url) {
  return WebShelfSites.find((site) => site.url === url) || null;
}

function getActivitySites() {
  if (typeof getRecentlyViewed === "function") return getRecentlyViewed();
  try {
    const sites = JSON.parse(WebShelfRuntime.storage.getItem(ACTIVITY_STORAGE_KEY) || "[]");
    return Array.isArray(sites) ? sites : [];
  } catch {
    return [];
  }
}

function formatLastVisited(timestamp) {
  if (!timestamp) return "Previous visit";
  const difference = Math.max(0, Date.now() - timestamp);
  const minutes = Math.floor(difference / 60000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes} ${minutes === 1 ? "minute" : "minutes"} ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} ${hours === 1 ? "hour" : "hours"} ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days} ${days === 1 ? "day" : "days"} ago`;
  return new Date(timestamp).toLocaleDateString();
}

function cutoffForPeriod() {
  if (currentActivityPeriod === "all") return 0;
  const days = Number(currentActivityPeriod);
  if (!Number.isFinite(days)) return 0;
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - days + 1);
  return start.getTime();
}

function periodVisitCount(site) {
  if (currentActivityPeriod === "all") return Number.isFinite(site.visits) ? site.visits : 0;
  const cutoff = cutoffForPeriod();
  const days = Array.isArray(site.visitDays) ? site.visitDays : [];
  return days.filter(item => item.day >= historyDay(cutoff)).reduce((sum,item) => sum + item.count, 0);
}

function periodLabel() {
  if (currentActivityPeriod === "7") return "last 7 days";
  if (currentActivityPeriod === "30") return "last 30 days";
  return "all time";
}

function getRenderedSites() {
  if (currentActivityView === "hidden") {
    return WebShelfSites.filter((site) => typeof isSiteHidden === "function" && isSiteHidden(site.url));
  }

  const cutoff = cutoffForPeriod();
  let sites = getActivitySites();

  if (currentActivityView === "history") {
    if (cutoff) sites = sites.filter((site) => site.lastVisited >= cutoff);
    return [...sites].sort((a, b) => b.lastVisited - a.lastVisited);
  }

  return sites
    .map((site) => ({ ...site, periodVisits: periodVisitCount(site) }))
    .filter((site) => site.periodVisits > 0)
    .sort((a, b) => b.periodVisits - a.periodVisits || b.lastVisited - a.lastVisited);
}

function activityRow(site, index) {
  const rank = String(index + 1).padStart(2, "0");
  const name = safeText(site.name);
  const url = safeText(site.url);
  const logo = site.icon
    ? `<img src="${safeText(site.icon)}" loading="lazy" decoding="async" alt="${name} logo">`
    : `<span>${name.charAt(0)}</span>`;

  const detail = currentActivityView === "hidden"
    ? "Hidden from directory"
    : currentActivityView === "most-visited"
      ? `${site.periodVisits ?? periodVisitCount(site)} ${(site.periodVisits ?? periodVisitCount(site)) === 1 ? "visit" : "visits"} · ${periodLabel()}`
      : formatLastVisited(site.lastVisited);

  const action = currentActivityView === "hidden"
    ? `<button class="activity-remove activity-unhide" type="button" data-unhide-url="${url}" aria-label="Show ${name} in directory">Show</button>`
    : `<button class="activity-remove" type="button" data-remove-activity="${url}" aria-label="Remove ${name} from activity">×</button>`;

  return `
    <div class="activity-row" data-site-url="${url}">
      <a class="activity-link" href="${url}" target="_blank" rel="noopener noreferrer">
        <span class="activity-rank">${rank}</span>
        <div class="activity-logo">${logo}</div>
        <div class="activity-site-info">
          <span class="activity-site-name-line"><span class="activity-site-name">${name}</span>${typeof renderSiteBadges === "function" ? renderSiteBadges(site) : ""}</span>
          <span class="activity-site-detail">${safeText(detail)}</span>
        </div>
        <span class="activity-arrow">↗</span>
      </a>
      ${action}
    </div>`;
}

function renderActivity() {
  if (!activityList || !activityInfo) return;
  syncHiddenActivityTab();
  const sites = getRenderedSites();
  if (activityPeriods) activityPeriods.hidden = currentActivityView === "hidden";

  if (!sites.length) {
    const message = currentActivityView === "hidden"
      ? "You haven't hidden any websites."
      : `No activity for ${periodLabel()}.`;
    activityInfo.textContent = message;
    activityList.innerHTML = `
      <div class="activity-empty">
        <h2>Nothing here yet</h2>
        <p>${safeText(message)}</p>
        <a href="./index.html">Explore directory</a>
      </div>`;
    return;
  }

  activityInfo.textContent = currentActivityView === "hidden"
    ? `${sites.length} hidden ${sites.length === 1 ? "website" : "websites"}`
    : `${sites.length} ${sites.length === 1 ? "website" : "websites"} · ${periodLabel()}`;
  activityList.innerHTML = sites.map(activityRow).join("");
  document.dispatchEvent(new CustomEvent("webshelf-sites-rendered"));
}

function saveActivitySites(sites) {
  saveRecentlyViewed(sites);
  document.dispatchEvent(new CustomEvent("webshelf-activity-changed"));
}

function removeActivity(url) {
  saveActivitySites(getActivitySites().filter((site) => site.url !== url));
}

document.querySelectorAll(".activity-tab").forEach((button) => {
  button.addEventListener("click", () => {
    currentActivityView = button.dataset.view;
    document.querySelectorAll(".activity-tab").forEach((tab) => tab.classList.toggle("active", tab === button));
    renderActivity();
  });
});

activityPeriods?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-period]");
  if (!button) return;
  currentActivityPeriod = button.dataset.period;
  activityPeriods.querySelectorAll(".activity-period").forEach((item) => item.classList.toggle("active", item === button));
  renderActivity();
});

activityList?.addEventListener("click", (event) => {
  const remove = event.target.closest("[data-remove-activity]");
  if (remove) {
    event.preventDefault();
    removeActivity(remove.dataset.removeActivity);
    return;
  }

  const unhide = event.target.closest("[data-unhide-url]");
  if (unhide) {
    event.preventDefault();
    setSiteHidden(unhide.dataset.unhideUrl, false);
    return;
  }

  if (event.target.closest("[data-badge-filter]")) return;
  const link = event.target.closest(".activity-link");
  if (!link) return;
  const site = canonicalSite(link.getAttribute("href")) || getActivitySites().find((item) => item.url === link.href);
  if (site && typeof addRecentlyViewed === "function") addRecentlyViewed(site);
});

document.querySelector("#activity-clear")?.addEventListener("click", async () => {
  const confirmed = window.WebShelfDialog
    ? await window.WebShelfDialog.confirm({
        title: "Clear activity?",
        message: "Your browsing history and visit counts will be removed. Favorites and hidden sites will stay.",
        confirmText: "Clear history",
        danger: true
      })
    : true;

  if (!confirmed) return;
  WebShelfRuntime.storage.removeItem(ACTIVITY_STORAGE_KEY);
  document.dispatchEvent(new CustomEvent("webshelf-activity-changed"));
});

document.addEventListener("webshelf-activity-changed", renderActivity);
document.addEventListener("webshelf-hidden-changed", () => {
  syncHiddenActivityTab();
  renderActivity();
});

applyActivityHash();
syncHiddenActivityTab();
renderActivity();

window.addEventListener("hashchange", () => { applyActivityHash(); renderActivity(); });

;

// preview.js
// ==================================================
// INLINE SITE PREVIEW
// ==================================================

(() => {
  const safeText = (value) => typeof escapeWebShelfText === "function"
    ? escapeWebShelfText(value)
    : String(value ?? "");

  function normalizeUrl(url) {
    try {
      const value = new URL(url, window.location.href).href;
      return value.endsWith("/") ? value.slice(0, -1) : value;
    } catch {
      return String(url || "");
    }
  }

  function findSite(url) {
    const wanted = normalizeUrl(url);
    return WebShelfSites.find((site) => normalizeUrl(site.url) === wanted);
  }

  function safeArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function mainLinkHTML(site) {
    return `
      <a class="site-preview-link site-preview-main-link" href="${safeText(site.url)}" target="_blank" rel="noopener noreferrer" data-preview-open-url="${safeText(site.url)}">
        Main site <span aria-hidden="true">↗</span>
      </a>`;
  }

  function mirrorLinksHTML(site) {
    const mirrors = safeArray(site.links).filter((link) => WebShelfRuntime.safeUrl(link?.url) && normalizeUrl(link.url) !== normalizeUrl(site.url));
    if (!mirrors.length) return "";

    return `
      <div class="site-preview-mirrors">
        <span class="site-preview-subheading">Mirrors & alternate links</span>
        <div class="site-preview-links">
          ${mirrors.map((link, index) => `
            <a class="site-preview-link" href="${safeText(link.url)}" target="_blank" rel="noopener noreferrer" data-preview-open-url="${safeText(site.url)}">
              ${safeText(link.label || `Mirror ${index + 1}`)} <span aria-hidden="true">↗</span>
            </a>`).join("")}
        </div>
      </div>`;
  }

  function descriptionHTML(site) {
    const description = String(site.description || "").trim();
    if (!description) return "";
    return `<p class="site-preview-description">${safeText(description)}</p>`;
  }

  function screenshotsHTML(site) {
    const screenshots = safeArray(site.screenshots).filter(src => WebShelfRuntime.safeUrl(src, true));
    if (!screenshots.length) return "";
    return `
      <section class="site-preview-section">
        <h4>Screenshots</h4>
        <div class="site-preview-screenshots">
          ${screenshots.map((src, index) => `
            <a href="${safeText(src)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${safeText(site.name)} screenshot ${index + 1}">
              <img src="${safeText(src)}" alt="${safeText(site.name)} screenshot ${index + 1}" loading="lazy" decoding="async">
            </a>`).join("")}
        </div>
      </section>`;
  }

  function highlightsHTML(site) {
    const highlights = safeArray(site.highlights).filter((item) => item?.text);
    if (!highlights.length) return "";
    return `
      <section class="site-preview-section site-preview-highlights">
        <h4>Highlights</h4>
        <div class="site-preview-highlights-list">
          ${highlights.map((item) => {
            const type = item.type === "bad" ? "bad" : "good";
            return `<div class="site-preview-highlight ${type}"><span class="site-preview-highlight-symbol">${type === "bad" ? "−" : "+"}</span><span>${safeText(item.text)}</span></div>`;
          }).join("")}
        </div>
      </section>`;
  }

  function secondaryActionsHTML(site) {
    const supportUrl = `./support.html?type=broken-link&site=${encodeURIComponent(site.name)}&url=${encodeURIComponent(site.url)}`;
    const hiddenAction = typeof isSiteHidden === "function"
      ? `<button class="site-preview-action site-preview-hide" type="button" data-preview-hide="${safeText(site.url)}">${isSiteHidden(site.url) ? "Show in directory" : "Hide / Not interested"}</button>`
      : "";

    return `
      <div class="site-preview-personal-actions">
        <a class="site-preview-action site-preview-report" href="${safeText(supportUrl)}">Report this link</a>
        ${hiddenAction}
      </div>`;
  }

  let previewId = 0;
  function buildPreview(site) {
    const panel = document.createElement("div");
    panel.className = "site-inline-preview";
    panel.id = "webshelf-preview-" + (++previewId);
    panel.hidden = true;
    panel.dataset.previewUrl = site.url;

    panel.innerHTML = `
      <div class="site-inline-preview-inner">
        <div class="site-preview-heading">
          <div>
            <span class="site-preview-category">${safeText(site.category)}</span>
            <div class="site-preview-title-line"><h3>${safeText(site.name)}</h3></div>
            ${descriptionHTML(site)}
          </div>
        </div>

        <section class="site-preview-section">
          <h4>Links</h4>
          <div class="site-preview-links">${mainLinkHTML(site)}</div>
          ${mirrorLinksHTML(site)}
        </section>

        ${screenshotsHTML(site)}
        ${highlightsHTML(site)}
        ${secondaryActionsHTML(site)}
      </div>`;
    return panel;
  }

  function closeRow(row) {
    const button = row.querySelector(".site-preview-toggle");
    const panel = row.nextElementSibling;
    if (!button || !panel?.classList.contains("site-inline-preview")) return;
    if (panel.contains(document.activeElement)) button.focus();
    panel.hidden = true;
    button.classList.remove("active");
    button.setAttribute("aria-expanded", "false");
  }

  function closeAll(exceptRow = null) {
    document.querySelectorAll(".site-row, .activity-row").forEach((row) => {
      if (row !== exceptRow) closeRow(row);
    });
  }

  function toggleRow(row) {
    const button = row.querySelector(".site-preview-toggle");
    const panel = row.nextElementSibling;
    if (!button || !panel?.classList.contains("site-inline-preview")) return;
    const willOpen = panel.hidden;
    closeAll(row);
    panel.hidden = !willOpen;
    button.classList.toggle("active", willOpen);
    button.setAttribute("aria-expanded", String(willOpen));
  }

  function prepareRow(row) {
    if (row.dataset.previewReady === "true") return;
    const link = row.querySelector(".site-link, .activity-link");
    if (!link?.href) return;
    const site = findSite(link.href);
    if (!site) return;

    row.dataset.previewReady = "true";
    const button = document.createElement("button");
    button.className = "site-preview-toggle";
    button.type = "button";
    button.dataset.previewUrl = site.url;
    button.setAttribute("aria-label", `Show ${site.name} preview`);
    button.setAttribute("aria-expanded", "false");
    button.innerHTML = `<span aria-hidden="true">›</span>`;

    const remove = row.querySelector(".activity-remove, .activity-unhide");
    if (remove) row.insertBefore(button, remove);
    else row.appendChild(button);
    const panel = buildPreview(site);
    button.setAttribute("aria-controls", panel.id);
    row.insertAdjacentElement("afterend", panel);
  }

  function scan(root = document) {
    root.querySelectorAll(".site-row, .activity-row").forEach(prepareRow);
  }

  function showUndoToast(site) {
    document.querySelector(".webshelf-undo-toast")?.remove();
    const toast = document.createElement("div");
    toast.setAttribute("role", "status");
    toast.className = "webshelf-undo-toast";
    toast.innerHTML = `<span>${safeText(site.name)} hidden.</span><button type="button">Undo</button>`;
    document.body.appendChild(toast);

    const timer = window.setTimeout(() => toast.remove(), 5000);
    toast.querySelector("button")?.addEventListener("click", () => {
      window.clearTimeout(timer);
      if (typeof setSiteHidden === "function") setSiteHidden(site.url, false);
      toast.remove();
    });
  }

  document.addEventListener("click", (event) => {
    const toggle = event.target.closest(".site-preview-toggle");
    if (toggle) {
      event.preventDefault();
      event.stopPropagation();
      const row = toggle.closest(".site-row, .activity-row");
      if (row) toggleRow(row);
      return;
    }

    const previewLink = event.target.closest(".site-preview-link");
    if (previewLink) {
      const site = findSite(previewLink.dataset.previewOpenUrl);
      if (site && typeof addRecentlyViewed === "function") addRecentlyViewed(site);
      return;
    }

    const hide = event.target.closest("[data-preview-hide]");
    if (hide) {
      event.preventDefault();
      const site = findSite(hide.dataset.previewHide);
      if (!site || typeof setSiteHidden !== "function") return;
      const willHide = !isSiteHidden(site.url);
      setSiteHidden(site.url, willHide);
      closeAll();
      if (willHide) showUndoToast(site);
    }
  });

  document.addEventListener("webshelf-sites-rendered", () => scan());
  const observer = new MutationObserver(records => {
    for (const record of records) for (const node of record.addedNodes) {
      if (!(node instanceof Element)) continue;
      if (node.matches(".site-row, .activity-row")) prepareRow(node);
      if (node.querySelector(".site-row, .activity-row")) scan(node);
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });
  scan();

  window.WebShelfPreview = {
    close: () => closeAll(),
    isOpen: () => Boolean(document.querySelector(".site-preview-toggle.active")),
    scan
  };
})();

;

// badge-filters.js
// ==================================================
// QUICK BADGE FILTERS
// ==================================================

(() => {
  function openBadgeFilter(badge) {
    if (!badge) return;

    if (window.WebShelfCategoryFilters?.applyBadge) {
      window.WebShelfCategoryFilters.applyBadge(badge);
      return;
    }

    if (window.WebShelfCollectionFilters?.applyBadge) {
      window.WebShelfCollectionFilters.applyBadge(badge);
      return;
    }

    window.location.href = `./collection.html?badge=${encodeURIComponent(badge)}`;
  }

  function isUsableBadge(element) {
    return element && !element.closest(".search-overlay") && element.hasAttribute("data-badge-filter");
  }

  document.addEventListener("click", (event) => {
    const badge = event.target.closest("[data-badge-filter]");
    if (!isUsableBadge(badge)) return;

    event.preventDefault();
    event.stopPropagation();
    openBadgeFilter(badge.dataset.badgeFilter);
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const badge = event.target.closest?.("[data-badge-filter]");
    if (!isUsableBadge(badge)) return;

    event.preventDefault();
    openBadgeFilter(badge.dataset.badgeFilter);
  });
})();

;

window.lucide?.createIcons?.();
